-- Cài thủ công 2 đề kiểm thử; không tự tái tạo khi khởi động.
BEGIN;
DO $validate$
DECLARE seed text; original_path text := current_setting('search_path'); check_schema text := 'mock_seed_check_' || substr(md5(random()::text),1,12); item jsonb; actual_columns text[]; expected_columns text[]; actual_rows bigint;
BEGIN
 SELECT init_sql_script INTO seed FROM public.practice_databases WHERE slug='quan-ly-sach-va-tac-gia';
 IF seed IS NULL THEN RAISE EXCEPTION 'Book practice database not found'; END IF;
 EXECUTE format('CREATE SCHEMA %I',check_schema);
 PERFORM set_config('search_path',format('%I,pg_catalog',check_schema),true);
 EXECUTE seed;
 FOR item IN SELECT value FROM jsonb_array_elements('[{"query": "SELECT b.book_id,b.title,p.name AS publisher_name,c.name AS category_name,b.price,b.stock_quantity FROM books b JOIN publishers p ON p.publisher_id=b.publisher_id JOIN categories c ON c.category_id=b.category_id WHERE b.stock_quantity>0 ORDER BY b.book_id", "columns": ["book_id", "title", "publisher_name", "category_name", "price", "stock_quantity"], "rows": 12}, {"query": "SELECT p.publisher_id,p.name AS publisher_name,COUNT(b.book_id) AS book_count,COALESCE(SUM(b.stock_quantity),0) AS total_stock,COALESCE(SUM(b.price*b.stock_quantity),0) AS inventory_value FROM publishers p LEFT JOIN books b ON b.publisher_id=p.publisher_id GROUP BY p.publisher_id,p.name ORDER BY p.publisher_id", "columns": ["publisher_id", "publisher_name", "book_count", "total_stock", "inventory_value"], "rows": 5}, {"query": "SELECT b.book_id,b.title,COUNT(ba.author_id) AS author_count FROM books b JOIN book_authors ba ON ba.book_id=b.book_id GROUP BY b.book_id,b.title HAVING COUNT(ba.author_id)>=2 ORDER BY b.book_id", "columns": ["book_id", "title", "author_count"], "rows": 5}, {"query": "SELECT b.book_id,b.title,b.category_id,b.price FROM books b WHERE b.price>(SELECT AVG(x.price) FROM books x WHERE x.category_id=b.category_id) ORDER BY b.book_id", "columns": ["book_id", "title", "category_id", "price"], "rows": 7}, {"query": "SELECT a.author_id,a.full_name AS author_name FROM authors a WHERE EXISTS (SELECT 1 FROM book_authors ba WHERE ba.author_id=a.author_id) AND NOT EXISTS (SELECT 1 FROM book_authors ba JOIN books b ON b.book_id=ba.book_id WHERE ba.author_id=a.author_id AND b.stock_quantity=0) ORDER BY a.author_id", "columns": ["author_id", "author_name"], "rows": 3}]'::jsonb) LOOP
  EXECUTE 'CREATE TEMP TABLE mock_seed_answer AS ' || (item->>'query');
  SELECT array_agg(column_name::text ORDER BY ordinal_position) INTO actual_columns FROM information_schema.columns WHERE table_schema LIKE 'pg_temp_%' AND table_name='mock_seed_answer';
  SELECT array_agg(value ORDER BY ord) INTO expected_columns FROM jsonb_array_elements_text(item->'columns') WITH ORDINALITY x(value,ord);
  EXECUTE 'SELECT COUNT(*) FROM mock_seed_answer' INTO actual_rows;
  IF actual_columns IS DISTINCT FROM expected_columns OR actual_rows <> (item->>'rows')::bigint THEN RAISE EXCEPTION 'SQL answer columns or row count mismatch'; END IF;
  EXECUTE 'DROP TABLE mock_seed_answer';
 END LOOP;
 PERFORM set_config('search_path',original_path,true);
 EXECUTE format('DROP SCHEMA %I CASCADE',check_schema);
END $validate$;
INSERT INTO mock_tests (id,title,slug,description,difficulty,duration_minutes,total_questions,passing_score,max_score,is_published) VALUES ('dee5e9aa-86f2-5ce2-829a-54571e5a1f4c','SQL tổng hợp — 20 câu trắc nghiệm (25 phút)','sql-trac-nghiem-tong-hop-20-cau-25-phut','Đề kiểm thử gồm 20 câu trắc nghiệm một đáp án đúng, mỗi câu 5 điểm. Nội dung SELECT, NULL, JOIN, GROUP BY, truy vấn con và xếp hạng. Tổng 100 điểm, đạt từ 70 điểm. Có thể đổi lựa chọn trước khi nộp bài.','MEDIUM',25,0,70,100,true) ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_tests (id,title,slug,description,difficulty,duration_minutes,total_questions,passing_score,max_score,is_published) VALUES ('229061fd-43eb-5b74-baca-08c78d44f006','SQL thực hành Sách — 5 câu truy vấn (30 phút)','sql-thuc-hanh-sach-5-cau-30-phut','Đề thực hành trên database Quản lý Sách & Tác giả (5 bảng, 50 bản ghi). Gồm JOIN, LEFT JOIN, GROUP BY/HAVING, truy vấn tương quan và EXISTS/NOT EXISTS. Mỗi câu 20 điểm, tổng 100, đạt từ 70 điểm; mỗi câu SQL tối đa 3 lần chấm thử.','MEDIUM',30,0,70,100,true) ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,content,points,sort_order,max_retries,mc_options,mc_correct_option,explanation) VALUES ('191d490c-98d3-52a2-8e2b-bae56c0bb0c0','dee5e9aa-86f2-5ce2-829a-54571e5a1f4c','MULTIPLE_CHOICE','Câu lệnh nào lấy đúng hai cột book_id và title từ bảng books?',5,1,3,'[{"id": "A", "text": "SELECT books FROM book_id, title;"}, {"id": "B", "text": "SELECT book_id, title FROM books;"}, {"id": "C", "text": "SELECT book_id AND title FROM books;"}, {"id": "D", "text": "FROM books SELECT book_id, title;"}]'::jsonb,'B','Danh sách cột đứng sau SELECT, phân cách bằng dấu phẩy; FROM chỉ định bảng nguồn.') ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,content,points,sort_order,max_retries,mc_options,mc_correct_option,explanation) VALUES ('6c634e2b-a306-5e61-a7d9-0461a3a4ecd1','dee5e9aa-86f2-5ce2-829a-54571e5a1f4c','MULTIPLE_CHOICE','Muốn lấy sách có giá từ 120000 đồng trở lên, điều kiện nào đúng?',5,2,3,'[{"id": "A", "text": "WHERE price > 120000"}, {"id": "B", "text": "WHERE price = 120000"}, {"id": "C", "text": "WHERE price >= 120000"}, {"id": "D", "text": "WHERE price <= 120000"}]'::jsonb,'C','Từ một ngưỡng trở lên gồm cả giá đúng bằng ngưỡng nên dùng >=.') ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,content,points,sort_order,max_retries,mc_options,mc_correct_option,explanation) VALUES ('66b665a0-2449-5cf3-a196-030fd2a4e22b','dee5e9aa-86f2-5ce2-829a-54571e5a1f4c','MULTIPLE_CHOICE','SELECT DISTINCT publisher_id, category_id FROM books loại trùng theo tiêu chí nào?',5,3,3,'[{"id": "A", "text": "Chỉ publisher_id"}, {"id": "B", "text": "Chỉ category_id"}, {"id": "C", "text": "Xóa các sách trùng khỏi bảng books"}, {"id": "D", "text": "Toàn bộ cặp (publisher_id, category_id) trong kết quả"}]'::jsonb,'D','DISTINCT xét toàn bộ danh sách cột được chọn và không xóa dữ liệu gốc.') ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,content,points,sort_order,max_retries,mc_options,mc_correct_option,explanation) VALUES ('29573eeb-1e0b-5703-9398-056bd4d3b049','dee5e9aa-86f2-5ce2-829a-54571e5a1f4c','MULTIPLE_CHOICE','Cách kiểm tra một giá trị đang là NULL trong SQL là gì?',5,4,3,'[{"id": "A", "text": "IS NULL"}, {"id": "B", "text": "= NULL"}, {"id": "C", "text": "== NULL"}, {"id": "D", "text": "IN NULL"}]'::jsonb,'A','NULL phải kiểm tra bằng IS NULL; phép so sánh = NULL trả UNKNOWN.') ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,content,points,sort_order,max_retries,mc_options,mc_correct_option,explanation) VALUES ('ed349128-7218-5b47-b0bd-6c7a54d7b9aa','dee5e9aa-86f2-5ce2-829a-54571e5a1f4c','MULTIPLE_CHOICE','Biểu thức A OR B AND C, khi không có ngoặc, được hiểu như thế nào?',5,5,3,'[{"id": "A", "text": "(A OR B) AND C"}, {"id": "B", "text": "A OR (B AND C)"}, {"id": "C", "text": "(A AND B) OR C"}, {"id": "D", "text": "NOT (A OR B OR C)"}]'::jsonb,'B','AND có độ ưu tiên cao hơn OR. Nên thêm ngoặc để ý định dễ đọc.') ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,content,points,sort_order,max_retries,mc_options,mc_correct_option,explanation) VALUES ('41d95bfc-4d19-5103-9cb7-0aae9f66c025','dee5e9aa-86f2-5ce2-829a-54571e5a1f4c','MULTIPLE_CHOICE','price BETWEEN 99000 AND 145000 bao gồm những giá trị biên nào?',5,6,3,'[{"id": "A", "text": "Không gồm cả hai đầu"}, {"id": "B", "text": "Chỉ gồm 99000"}, {"id": "C", "text": "Gồm cả 99000 và 145000"}, {"id": "D", "text": "Chỉ gồm 145000"}]'::jsonb,'C','BETWEEN là khoảng đóng, tương đương >= cận dưới AND <= cận trên.') ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,content,points,sort_order,max_retries,mc_options,mc_correct_option,explanation) VALUES ('a41e4931-4785-5795-ba5c-df99d72ad077','dee5e9aa-86f2-5ce2-829a-54571e5a1f4c','MULTIPLE_CHOICE','Trong mẫu LIKE, ký tự _ đại diện cho gì?',5,7,3,'[{"id": "A", "text": "Không hoặc nhiều ký tự"}, {"id": "B", "text": "Chỉ chữ số"}, {"id": "C", "text": "Một dấu gạch dưới theo nghĩa đen trong mọi trường hợp"}, {"id": "D", "text": "Đúng một ký tự"}]'::jsonb,'D','Dấu _ là ký tự đại diện đúng một ký tự; % đại diện không hoặc nhiều ký tự.') ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,content,points,sort_order,max_retries,mc_options,mc_correct_option,explanation) VALUES ('28623941-9528-5d18-978a-5f0c0552ef60','dee5e9aa-86f2-5ce2-829a-54571e5a1f4c','MULTIPLE_CHOICE','Muốn lấy đúng ba sách đắt nhất và có thứ tự ổn định khi đồng giá, cách nào phù hợp nhất?',5,8,3,'[{"id": "A", "text": "ORDER BY price DESC, book_id ASC LIMIT 3"}, {"id": "B", "text": "ORDER BY price ASC LIMIT 3"}, {"id": "C", "text": "LIMIT 3, không cần ORDER BY"}, {"id": "D", "text": "ORDER BY price DESC OFFSET 3"}]'::jsonb,'A','Sắp giá giảm dần, thêm khóa duy nhất để xử lý đồng giá rồi giới hạn ba dòng.') ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,content,points,sort_order,max_retries,mc_options,mc_correct_option,explanation) VALUES ('26ef991b-a65c-544e-ac9b-443325ecb76a','dee5e9aa-86f2-5ce2-829a-54571e5a1f4c','MULTIPLE_CHOICE','Bảng books có 15 sách; mỗi sách có một publisher_id NOT NULL hợp lệ. INNER JOIN books với publishers theo khóa đó tạo bao nhiêu dòng?',5,9,3,'[{"id": "A", "text": "5"}, {"id": "B", "text": "15"}, {"id": "C", "text": "20"}, {"id": "D", "text": "75"}]'::jsonb,'B','Mỗi sách khớp đúng một nhà xuất bản nên tạo một dòng, tổng cộng 15 dòng.') ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,content,points,sort_order,max_retries,mc_options,mc_correct_option,explanation) VALUES ('9e24d1d3-496b-5457-a298-7c2d35f2aeb6','dee5e9aa-86f2-5ce2-829a-54571e5a1f4c','MULTIPLE_CHOICE','Có 5 nhà xuất bản và 15 sách. Mỗi sách thuộc đúng một nhà xuất bản hợp lệ; 4 nhà xuất bản có sách, 1 nhà xuất bản chưa có sách. publishers LEFT JOIN books theo publisher_id tạo bao nhiêu dòng?',5,10,3,'[{"id": "A", "text": "5"}, {"id": "B", "text": "15"}, {"id": "C", "text": "16"}, {"id": "D", "text": "20"}]'::jsonb,'C','Có 15 dòng sách khớp cộng một dòng đệm NULL cho nhà xuất bản chưa có sách.') ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,content,points,sort_order,max_retries,mc_options,mc_correct_option,explanation) VALUES ('c3657fa7-2c7d-5a8f-9e71-d740f4b3e2bf','dee5e9aa-86f2-5ce2-829a-54571e5a1f4c','MULTIPLE_CHOICE','books có 15 sách; book_authors có 20 cặp hợp lệ, không trùng (book_id, author_id); authors có đủ tác giả được tham chiếu. JOIN ba bảng theo đúng các khóa tạo bao nhiêu dòng sách–tác giả?',5,11,3,'[{"id": "A", "text": "5"}, {"id": "B", "text": "15"}, {"id": "C", "text": "75"}, {"id": "D", "text": "20"}]'::jsonb,'D','Mỗi dòng liên kết hợp lệ tạo một cặp sách–tác giả, nên có 20 dòng.') ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,content,points,sort_order,max_retries,mc_options,mc_correct_option,explanation) VALUES ('42659fbf-f3df-5b26-871c-fda99c96161e','dee5e9aa-86f2-5ce2-829a-54571e5a1f4c','MULTIPLE_CHOICE','Khóa chính phù hợp cho bảng liên kết book_authors, với yêu cầu một tác giả không bị lặp trong cùng một sách, là gì?',5,12,3,'[{"id": "A", "text": "PRIMARY KEY (book_id, author_id)"}, {"id": "B", "text": "PRIMARY KEY (book_id) vì một sách chỉ có một tác giả"}, {"id": "C", "text": "PRIMARY KEY (author_id) vì một tác giả chỉ viết một sách"}, {"id": "D", "text": "Không cần khóa hoặc ràng buộc duy nhất"}]'::jsonb,'A','Khóa ghép bảo đảm từng cặp sách–tác giả duy nhất và vẫn cho phép quan hệ nhiều–nhiều.') ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,content,points,sort_order,max_retries,mc_options,mc_correct_option,explanation) VALUES ('87fdfb31-5a6a-526d-ae9d-e862b2d05154','dee5e9aa-86f2-5ce2-829a-54571e5a1f4c','MULTIPLE_CHOICE','Sau publishers LEFT JOIN books, muốn đếm số sách mỗi nhà xuất bản và trả 0 cho đơn vị chưa có sách, dùng biểu thức nào?',5,13,3,'[{"id": "A", "text": "COUNT(*)"}, {"id": "B", "text": "COUNT(b.book_id), với b.book_id là khóa chính của books"}, {"id": "C", "text": "COUNT(p.publisher_id)"}, {"id": "D", "text": "COUNT(COALESCE(b.book_id, 0))"}]'::jsonb,'B','COUNT(b.book_id) bỏ qua NULL của dòng không khớp, trong khi ba biểu thức còn lại vẫn đếm dòng đệm.') ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,content,points,sort_order,max_retries,mc_options,mc_correct_option,explanation) VALUES ('ac4aa22b-6681-5c23-90e9-0dc76a562b9a','dee5e9aa-86f2-5ce2-829a-54571e5a1f4c','MULTIPLE_CHOICE','Sau GROUP BY publisher_id, điều kiện chỉ giữ nhóm có ít nhất bốn sách nên viết ở đâu?',5,14,3,'[{"id": "A", "text": "WHERE COUNT(*) >= 4"}, {"id": "B", "text": "ORDER BY COUNT(*) >= 4"}, {"id": "C", "text": "HAVING COUNT(*) >= 4"}, {"id": "D", "text": "LIMIT COUNT(*) >= 4"}]'::jsonb,'C','HAVING lọc kết quả tổng hợp theo nhóm; WHERE lọc từng dòng trước tổng hợp.') ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,content,points,sort_order,max_retries,mc_options,mc_correct_option,explanation) VALUES ('f2e7c71d-c188-5fde-9b49-850159fd66af','dee5e9aa-86f2-5ce2-829a-54571e5a1f4c','MULTIPLE_CHOICE','Trên bảng books, AVG(price) biểu thị điều gì nếu mỗi dòng là một đầu sách?',5,15,3,'[{"id": "A", "text": "Tổng giá trị tồn kho"}, {"id": "B", "text": "Giá trung bình có trọng số stock_quantity"}, {"id": "C", "text": "Giá lớn nhất của các sách còn hàng"}, {"id": "D", "text": "Giá trung bình giữa các đầu sách có price không NULL, không tính trọng số tồn kho"}]'::jsonb,'D','AVG(price) không dùng stock_quantity. Bình quân có trọng số cần SUM(price*stock_quantity)/SUM(stock_quantity).') ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,content,points,sort_order,max_retries,mc_options,mc_correct_option,explanation) VALUES ('5bcf2309-2025-5059-b914-adecbb816365','dee5e9aa-86f2-5ce2-829a-54571e5a1f4c','MULTIPLE_CHOICE','Trong PostgreSQL, truy vấn con được dùng như một giá trị vô hướng nhưng trả hai dòng sẽ dẫn đến điều gì?',5,16,3,'[{"id": "A", "text": "Lỗi vì truy vấn con vô hướng trả nhiều hơn một dòng"}, {"id": "B", "text": "Tự lấy dòng đầu tiên"}, {"id": "C", "text": "Tự lấy giá trị lớn nhất"}, {"id": "D", "text": "Tự chuyển thành một danh sách dùng cho dấu ="}]'::jsonb,'A','Vị trí vô hướng chỉ chấp nhận tối đa một dòng và một cột. IN/ANY hoặc tổng hợp giải quyết bài toán khác.') ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,content,points,sort_order,max_retries,mc_options,mc_correct_option,explanation) VALUES ('88c6c577-87a6-58c1-8c9c-c35bb59a49c2','dee5e9aa-86f2-5ce2-829a-54571e5a1f4c','MULTIPLE_CHOICE','EXISTS(SELECT 1 FROM book_authors ba WHERE ba.author_id = a.author_id) được dùng để lọc authors a. Nếu một tác giả có bốn dòng liên kết phù hợp thì dòng tác giả ngoài xuất hiện mấy lần?',5,17,3,'[{"id": "A", "text": "4 lần vì EXISTS cũng là JOIN"}, {"id": "B", "text": "1 lần, nếu nguồn authors có một dòng cho tác giả đó"}, {"id": "C", "text": "0 lần vì SELECT 1 không trả dữ liệu thật"}, {"id": "D", "text": "Không xác định, luôn cần DISTINCT"}]'::jsonb,'B','EXISTS chỉ kiểm tra có ít nhất một dòng; nó không ghép từng dòng liên kết vào đầu ra.') ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,content,points,sort_order,max_retries,mc_options,mc_correct_option,explanation) VALUES ('4abe412f-1e20-5f04-9462-9ddf8809717b','dee5e9aa-86f2-5ce2-829a-54571e5a1f4c','MULTIPLE_CHOICE','Trong PostgreSQL, biểu thức 2 NOT IN (1, NULL::integer) có giá trị gì?',5,18,3,'[{"id": "A", "text": "TRUE"}, {"id": "B", "text": "FALSE"}, {"id": "C", "text": "NULL (UNKNOWN)"}, {"id": "D", "text": "Lỗi cú pháp"}]'::jsonb,'C','Không khớp 1 nhưng so sánh với NULL là UNKNOWN; NOT IN không thể kết luận TRUE.') ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,content,points,sort_order,max_retries,mc_options,mc_correct_option,explanation) VALUES ('43c86de0-5cb2-596f-b6ae-7a613d02dd1d','dee5e9aa-86f2-5ce2-829a-54571e5a1f4c','MULTIPLE_CHOICE','DENSE_RANK() OVER (ORDER BY price DESC) cho ba dòng giá lần lượt 180000, 180000, 145000 những hạng nào?',5,19,3,'[{"id": "A", "text": "1, 2, 3"}, {"id": "B", "text": "1, 1, 3"}, {"id": "C", "text": "3, 2, 1"}, {"id": "D", "text": "1, 1, 2"}]'::jsonb,'D','DENSE_RANK cho các dòng đồng giá cùng hạng và không để khoảng trống sau nhóm đồng hạng.') ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,content,points,sort_order,max_retries,mc_options,mc_correct_option,explanation) VALUES ('6ad9f569-95d6-5e81-8d4e-a08b32cfdb8c','dee5e9aa-86f2-5ce2-829a-54571e5a1f4c','MULTIPLE_CHOICE','Thứ tự xử lý logic phù hợp của một SELECT có gom nhóm là gì? (Không phải thứ tự thực thi vật lý.)',5,20,3,'[{"id": "A", "text": "FROM/JOIN → WHERE → GROUP BY → HAVING → SELECT → ORDER BY"}, {"id": "B", "text": "SELECT → WHERE → FROM → GROUP BY → HAVING → ORDER BY"}, {"id": "C", "text": "FROM → HAVING → WHERE → SELECT → GROUP BY → ORDER BY"}, {"id": "D", "text": "ORDER BY → FROM → WHERE → SELECT → HAVING → GROUP BY"}]'::jsonb,'A','Đầu vào hình thành từ FROM/JOIN, lọc dòng bằng WHERE, nhóm và lọc nhóm, tạo cột đầu ra rồi sắp xếp.') ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,database_id,content,points,sort_order,requirements,expected_columns,solution_query,max_retries) SELECT 'c30e6a9b-d862-5956-bc53-1e3a277e89b8','229061fd-43eb-5b74-baca-08c78d44f006','SQL_QUERY',d.id,'### Câu 1. Sách còn hàng cùng nhà xuất bản và thể loại

Liệt kê các sách có stock_quantity > 0, kèm tên nhà xuất bản và thể loại. Mỗi sách chỉ xuất hiện một lần. Sắp xếp book_id tăng dần.

Trả về đúng tên và thứ tự cột: `book_id`, `title`, `publisher_name`, `category_name`, `price`, `stock_quantity`.',20,1,'["Liệt kê các sách có stock_quantity > 0, kèm tên nhà xuất bản và thể loại. Mỗi sách chỉ xuất hiện một lần. Sắp xếp book_id tăng dần.", "Đặt tên và thứ tự các cột đúng như đề bài.", "Chỉ dùng truy vấn SELECT; không sửa dữ liệu gốc."]'::jsonb,'["book_id", "title", "publisher_name", "category_name", "price", "stock_quantity"]'::jsonb,'SELECT b.book_id,b.title,p.name AS publisher_name,c.name AS category_name,b.price,b.stock_quantity FROM books b JOIN publishers p ON p.publisher_id=b.publisher_id JOIN categories c ON c.category_id=b.category_id WHERE b.stock_quantity>0 ORDER BY b.book_id',3 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,database_id,content,points,sort_order,requirements,expected_columns,solution_query,max_retries) SELECT '0a8dd8ec-d569-5f5b-9104-ff9343b3ec64','229061fd-43eb-5b74-baca-08c78d44f006','SQL_QUERY',d.id,'### Câu 2. Thống kê kho của mọi nhà xuất bản

Với mỗi nhà xuất bản, tính số đầu sách, tổng số cuốn tồn kho và tổng giá trị tồn kho (price * stock_quantity). Giữ cả nhà xuất bản chưa có sách, các số tổng của họ bằng 0. Sắp xếp publisher_id tăng dần.

Trả về đúng tên và thứ tự cột: `publisher_id`, `publisher_name`, `book_count`, `total_stock`, `inventory_value`.',20,2,'["Với mỗi nhà xuất bản, tính số đầu sách, tổng số cuốn tồn kho và tổng giá trị tồn kho (price * stock_quantity). Giữ cả nhà xuất bản chưa có sách, các số tổng của họ bằng 0. Sắp xếp publisher_id tăng dần.", "Đặt tên và thứ tự các cột đúng như đề bài.", "Chỉ dùng truy vấn SELECT; không sửa dữ liệu gốc."]'::jsonb,'["publisher_id", "publisher_name", "book_count", "total_stock", "inventory_value"]'::jsonb,'SELECT p.publisher_id,p.name AS publisher_name,COUNT(b.book_id) AS book_count,COALESCE(SUM(b.stock_quantity),0) AS total_stock,COALESCE(SUM(b.price*b.stock_quantity),0) AS inventory_value FROM publishers p LEFT JOIN books b ON b.publisher_id=p.publisher_id GROUP BY p.publisher_id,p.name ORDER BY p.publisher_id',3 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,database_id,content,points,sort_order,requirements,expected_columns,solution_query,max_retries) SELECT '2d223fe9-64b0-56a4-bd3c-e8551cdb28ba','229061fd-43eb-5b74-baca-08c78d44f006','SQL_QUERY',d.id,'### Câu 3. Các sách có đồng tác giả

Liệt kê các sách có ít nhất hai tác giả, kèm số tác giả tương ứng. Dùng GROUP BY và HAVING. Sắp xếp book_id tăng dần.

Trả về đúng tên và thứ tự cột: `book_id`, `title`, `author_count`.',20,3,'["Liệt kê các sách có ít nhất hai tác giả, kèm số tác giả tương ứng. Dùng GROUP BY và HAVING. Sắp xếp book_id tăng dần.", "Đặt tên và thứ tự các cột đúng như đề bài.", "Chỉ dùng truy vấn SELECT; không sửa dữ liệu gốc."]'::jsonb,'["book_id", "title", "author_count"]'::jsonb,'SELECT b.book_id,b.title,COUNT(ba.author_id) AS author_count FROM books b JOIN book_authors ba ON ba.book_id=b.book_id GROUP BY b.book_id,b.title HAVING COUNT(ba.author_id)>=2 ORDER BY b.book_id',3 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,database_id,content,points,sort_order,requirements,expected_columns,solution_query,max_retries) SELECT '8b7915be-9d48-5c8c-bb44-8cbbc182ffd0','229061fd-43eb-5b74-baca-08c78d44f006','SQL_QUERY',d.id,'### Câu 4. Sách đắt hơn trung bình cùng thể loại

Dùng truy vấn con tương quan để tìm sách có price lớn hơn giá trung bình các sách thuộc chính thể loại của nó. So sánh trực tiếp với AVG, không làm tròn trước khi so sánh. Sắp xếp book_id tăng dần.

Trả về đúng tên và thứ tự cột: `book_id`, `title`, `category_id`, `price`.',20,4,'["Dùng truy vấn con tương quan để tìm sách có price lớn hơn giá trung bình các sách thuộc chính thể loại của nó. So sánh trực tiếp với AVG, không làm tròn trước khi so sánh. Sắp xếp book_id tăng dần.", "Đặt tên và thứ tự các cột đúng như đề bài.", "Chỉ dùng truy vấn SELECT; không sửa dữ liệu gốc."]'::jsonb,'["book_id", "title", "category_id", "price"]'::jsonb,'SELECT b.book_id,b.title,b.category_id,b.price FROM books b WHERE b.price>(SELECT AVG(x.price) FROM books x WHERE x.category_id=b.category_id) ORDER BY b.book_id',3 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO mock_test_questions (id,test_id,question_type,database_id,content,points,sort_order,requirements,expected_columns,solution_query,max_retries) SELECT '5b5d7b6b-4865-5121-9532-2ad480c1c4b0','229061fd-43eb-5b74-baca-08c78d44f006','SQL_QUERY',d.id,'### Câu 5. Tác giả có sách nhưng không có sách hết hàng

Lấy các tác giả có ít nhất một sách và không tham gia bất kỳ sách nào có stock_quantity = 0. Tính cả vai trò tác giả chính và đồng tác giả. Dùng EXISTS kết hợp NOT EXISTS; mỗi tác giả xuất hiện một lần. Sắp xếp author_id tăng dần.

Trả về đúng tên và thứ tự cột: `author_id`, `author_name`.',20,5,'["Lấy các tác giả có ít nhất một sách và không tham gia bất kỳ sách nào có stock_quantity = 0. Tính cả vai trò tác giả chính và đồng tác giả. Dùng EXISTS kết hợp NOT EXISTS; mỗi tác giả xuất hiện một lần. Sắp xếp author_id tăng dần.", "Đặt tên và thứ tự các cột đúng như đề bài.", "Chỉ dùng truy vấn SELECT; không sửa dữ liệu gốc."]'::jsonb,'["author_id", "author_name"]'::jsonb,'SELECT a.author_id,a.full_name AS author_name FROM authors a WHERE EXISTS (SELECT 1 FROM book_authors ba WHERE ba.author_id=a.author_id) AND NOT EXISTS (SELECT 1 FROM book_authors ba JOIN books b ON b.book_id=ba.book_id WHERE ba.author_id=a.author_id AND b.stock_quantity=0) ORDER BY a.author_id',3 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
UPDATE mock_tests t SET total_questions=(SELECT COUNT(*) FROM mock_test_questions q WHERE q.test_id=t.id) WHERE t.id='dee5e9aa-86f2-5ce2-829a-54571e5a1f4c';
DO $$ BEGIN IF (SELECT count(*) FROM mock_test_questions WHERE test_id='dee5e9aa-86f2-5ce2-829a-54571e5a1f4c')<>20 OR (SELECT sum(points) FROM mock_test_questions WHERE test_id='dee5e9aa-86f2-5ce2-829a-54571e5a1f4c')<>100 THEN RAISE EXCEPTION 'Invalid question count or score'; END IF; END $$;
UPDATE mock_tests t SET total_questions=(SELECT COUNT(*) FROM mock_test_questions q WHERE q.test_id=t.id) WHERE t.id='229061fd-43eb-5b74-baca-08c78d44f006';
DO $$ BEGIN IF (SELECT count(*) FROM mock_test_questions WHERE test_id='229061fd-43eb-5b74-baca-08c78d44f006')<>5 OR (SELECT sum(points) FROM mock_test_questions WHERE test_id='229061fd-43eb-5b74-baca-08c78d44f006')<>100 THEN RAISE EXCEPTION 'Invalid question count or score'; END IF; END $$;
COMMIT;
